 public static function unionMinutes(array $intervals):int {if(!$intervals){return 0;}usort($intervals,fn($a,$b)=>$a[0]<=>$b[0]);$sum=0;[$a,$b]=array_shift($intervals);foreach($intervals as[$c,$d]){if($c<=$b){$b=max($b,$d);}else{$sum+=max(0,$b-$a);[$a,$b]=[$c,$d];}}return $sum+max(0,$b-$a);}
 public static function gaps(int $start,int $end,array $intervals):array {usort($intervals,fn($a,$b)=>$a[0]<=>$b[0]);$cursor=$start;$out=[];foreach($intervals as[$a,$b]){$a=max($start,$a);$b=min($end,$b);if($b<=$start||$a>=$end){continue;}if($a>$cursor){$out[]=[$cursor,$a];}$cursor=max($cursor,$b);}if($cursor<$end){$out[]=[$cursor,$end];}return $out;}
 public static function layout(array $rows,int $start,int $end):array {
  usort($rows,fn($a,$b)=>[$a['start_time'],$a['end_time'],$a['key']]<=>[$b['start_time'],$b['end_time'],$b['key']]);$groups=[];$group=[];$until=-1;foreach($rows as$row){$a=CentrePlanning::minutes($row['start_time']);$b=CentrePlanning::minutes($row['end_time']);if($group&&$a>=$until){$groups[]=$group;$group=[];$until=-1;}$group[]=$row;$until=max($until,$b);}if($group){$groups[]=$group;}$result=[];foreach($groups as$group){$ends=[];$placed=[];foreach($group as$row){$a=CentrePlanning::minutes($row['start_time']);$b=CentrePlanning::minutes($row['end_time']);$lane=0;while(isset($ends[$lane])&&$ends[$lane]>$a){$lane++;}$ends[$lane]=$b;$row['lane']=$lane;$row['top']=round(100*($a-$start)/($end-$start),3);$row['height']=round(100*($b-$a)/($end-$start),3);$placed[]=$row;}$lanes=count($ends);foreach($placed as$row){$row['left']=round(100*$row['lane']/$lanes,3);$row['width']=round(100/$lanes,3);$row['visual_overlap']=$lanes>1;$result[]=$row;}}return $result;
 }
 public static function board(User $user,string $week,string $mode='staff',?string $site=null,?int $selected=null,bool $dayCards=false,bool $shared=false):array {
  abort_unless(CentrePlanning::staff($user),403);$planner=CentrePlanning::allowed($user);if(!$planner&&!$shared){$mode='staff';$selected=$user->id;$site=null;}abort_unless(in_array($mode,['staff','room','group'],true),422);$monday=Carbon::parse($week,config('app.timezone'))->startOfWeek();$dates=array_map(fn($n)=>$monday->copy()->addDays($n)->toDateString(),range(0,6));$busy=CentrePlanning::busy($dates);$all=$busy['rows'];if(!$planner&&!$shared){$all=array_values(array_filter($all,fn($r)=>$r['staff_id']===$user->id));}if($shared){$fields=['key','work_date','start_time','end_time','staff_id','room_id','group_id','kind','site','external','stale','headcount','cover_current'];foreach($all as&$public){$public=collect($public)->only($fields)->all()+['plan_id'=>null,'members'=>[],'title'=>$public['kind']==='Non-working'?'Unavailable':$public['kind'].' — published diary'];}unset($public);}$rows=array_values(array_filter($all,fn($r)=>(!$site||$r['site']===$site)&&(!$selected||$r[$mode==='staff'?'staff_id':($mode==='room'?'room_id':'group_id')]===$selected)));abort_if(count($rows)>2000,422,'Narrow the selected resource/site.');if($dayCards&&!collect($rows)->contains(fn($x)=>Carbon::parse($x['work_date'])->isWeekend())&&!($mode==='staff'&&\App\Models\TimetableFlexibleDay::where('state','Active')->whereIn(\Illuminate\Support\Facades\DB::raw('DATE(work_date)'),array_slice($dates,5))->when($selected,fn($q)=>$q->where('staff_id',$selected))->exists())){$dates=array_slice($dates,0,5);}$from=480;$to=1080;foreach($rows as$row){$from=min($from,CentrePlanning::minutes($row['start_time']));$to=max($to,CentrePlanning::minutes($row['end_time']));}
  $resources=match($mode){'room'=>Room::orderBy('site')->orderBy('name')->get()->filter(fn($r)=>(!$site||$r->site===$site))->map(fn($r)=>['id'=>$r->id,'name'=>$r->site.' · '.$r->name])->all(),'group'=>TutorGroup::orderBy('name')->get()->map(fn($g)=>['id'=>$g->id,'name'=>$g->name])->all(),default=>User::orderBy('name')->get()->filter(fn($u)=>(CentrePlanning::staff($u)||collect($rows)->contains('staff_id',$u->id)))->map(fn($u)=>['id'=>$u->id,'name'=>$u->name.($u->active?'':' (inactive)'),'section'=>TimetableGovernance::sectionLabel($u)])->all()};
  if($mode==='staff'){usort($resources,fn($a,$b)=>[($a['section']==='Teaching tutors'?0:1),$a['name']]<=>[($b['section']==='Teaching tutors'?0:1),$b['name']]);}$options=$resources;$resources=array_values(array_filter($resources,fn($r)=>!$selected||$r['id']===$selected));if(count($resources)>100){abort(422,'Select one resource to show this grid.');}$key=match($mode){'room'=>'room_id','group'=>'group_id',default=>'staff_id'};$cells=[];$totals=[];
  // Window availability uses all known bookings for that staff, even when a site filter hides a card.
  foreach($resources as$res){$total=['known_capacity'=>0,'available'=>0,'teaching'=>0,'other_work'=>0,'non_working'=>0,'unknown_days'=>0,'conflicts'=>0];foreach($dates as$date){$items=array_values(array_filter($rows,fn($x)=>$x[$key]===$res['id']&&$x['work_date']===$date));$allStaff=array_values(array_filter($all,fn($x)=>$x['staff_id']===$res['id']&&$x['work_date']===$date));$w=$mode==='staff'&&!$shared?Window::where('user_id',$res['id'])->whereDate('work_date',$date)->first():null;$known=$w&&CentrePlanning::windowIntact($w)&&!$busy['uncertain']&&($who=User::find($res['id']))&&CentrePlanning::staff($who);$gaps=[];$stats=['capacity'=>null,'available'=>null,'teaching'=>0,'other_work'=>0,'non_working'=>0];if($mode==='staff'&&$known){if($w->working){$a=CentrePlanning::minutes($w->start_time);$b=CentrePlanning::minutes($w->end_time);$from=min($from,$a);$to=max($to,$b);$busyIntervals=[];$types=['teaching'=>[],'other_work'=>[],'non_working'=>[]];foreach($allStaff as$i){$v=[max($a,CentrePlanning::minutes($i['start_time'])),min($b,CentrePlanning::minutes($i['end_time']))];if($v[1]>$v[0]){$busyIntervals[]=$v;$type=$i['kind']==='Teaching'?'teaching':($i['kind']==='Non-working'?'non_working':'other_work');$types[$type][]=$v;}}foreach($types as$t=>$intervals){$stats[$t]=self::unionMinutes($intervals);}$stats['capacity']=$b-$a-$stats['non_working'];$gaps=self::gaps($a,$b,$busyIntervals);$stats['available']=array_sum(array_map(fn($g)=>$g[1]-$g[0],$gaps));}else{$stats['capacity']=0;$stats['available']=0;}}elseif($mode==='staff'){$total['unknown_days']++;}
   $conflicts=[];for($i=0;$i<count($items);$i++){for($j=$i+1;$j<count($items);$j++){if(CentrePlanning::shared($items[$i],$items[$j])&&CentrePlanning::overlap($items[$i],$items[$j])){$conflicts[]=$items[$i]['key'].' / '.$items[$j]['key'];}}}foreach(['teaching','other_work','non_working']as$t){$total[$t]+=$stats[$t];}$total['known_capacity']+=$stats['capacity']??0;$total['available']+=$stats['available']??0;$total['conflicts']+=count($conflicts);$flex=$mode==='staff'?TimetableDuties::day($res['id'],$date):null;$cells[$res['id']][$date]=['flexible'=>$shared?null:$flex,'flexible_current'=>$flex?TimetableDuties::dayCurrent($flex):false,'items'=>$items,'window'=>$w,'known'=>(bool)$known,'gaps'=>$gaps,'stats'=>$stats,'conflicts'=>$conflicts];}$total['pattern']=$mode==='staff'&&!$shared?TimetableDuties::pattern($res['id'],$dates,$all):null;$totals[$res['id']]=$total;}
  // Same time scale across every cell, expanded to include out-of-hours records/windows.
  foreach($cells as$id=>$days){foreach($days as$date=>$cell){$enriched=array_map(fn($x)=>$x+['group_context'=>$x['group_id']?TimetableDuties::facts($x['group_id']):null,'room_name'=>$x['room_id']?Room::find($x['room_id'])?->name:null,'staff_name'=>User::find($x['staff_id'])?->name],$cell['items']);if($shared){foreach($enriched as&$safe){if($safe['group_context']){$safe['group_context']['notes']=null;}}unset($safe);}$cells[$id][$date]['positions']=self::layout($enriched,$from,$to);foreach($cell['gaps']as[$a,$b]){foreach(TimetableDuties::gapParts($id,$date,$a,$b)as[$x,$y,$label]){$cells[$id][$date]['gap_positions'][]=['start'=>CentrePlanning::clock($x),'end'=>CentrePlanning::clock($y),'minutes'=>$y-$x,'label'=>$label,'top'=>100*($x-$from)/($to-$from),'height'=>100*($y-$x)/($to-$from)];}}}}
  $staffNames=User::whereIn('id',array_column($rows,'staff_id'))->pluck('name','id');$roomNames=Room::whereIn('id',array_filter(array_column($rows,'room_id')))->pluck('name','id');$groupNames=TutorGroup::whereIn('id',array_filter(array_column($rows,'group_id')))->pluck('name','id');foreach($rows as&$item){$item['group_context']=$item['group_id']?TimetableDuties::facts($item['group_id']):null;if($shared&&$item['group_context']){$item['group_context']['notes']=null;}$item['staff_name']=$staffNames->get($item['staff_id'],'Staff source needs checking');$item['room_name']=$item['room_id']?$roomNames->get($item['room_id'],'Room source needs checking'):null;$item['group_name']=$item['group_id']?$groupNames->get($item['group_id'],'Group source needs checking'):null;}unset($item);
  return ['planner'=>$planner,'mode'=>$mode,'week'=>$monday->toDateString(),'dates'=>$dates,'site'=>$site,'selected'=>$selected,'safe_shared'=>$shared,'day_cards'=>$dayCards,'resources'=>$resources,'options'=>$options,'cells'=>$cells,'totals'=>$totals,'rows'=>$rows,'scale'=>['start'=>CentrePlanning::clock($from),'end'=>CentrePlanning::clock($to),'minutes'=>$to-$from],'uncertain'=>$planner?$busy['uncertain']:($busy['uncertain']?['Some scheduling sources need a planner check; no complete-availability claim.']:[]),'drafts_included'=>false];
 }
